define('categorySearch', ['alerts', 'bootstrap', 'api'], function (alerts, bootstrap, api) {
	const categorySearch = {};

	categorySearch.init = function (el, options) {
		let categoriesList = null;
		options = options || {};
		options.privilege = options.privilege || 'topics:read';
		options.states = options.states || ['watching', 'tracking', 'notwatching', 'ignoring'];
		options.cacheList = options.hasOwnProperty('cacheList') ? options.cacheList : true;

		let localCategories = [];
		if (Array.isArray(options.localCategories)) {
			localCategories = options.localCategories.map(c => ({ ...c }));
		}
		options.selectedCids = options.selectedCids || ajaxify.data.selectedCids || [];

		const searchEl = el.find('[component="category-selector-search"]');
		if (!searchEl.length) {
			return;
		}

		const toggleVisibility = searchEl.parent('[component="category/dropdown"]').length > 0 ||
			searchEl.parent('[component="category-selector"]').length > 0;

		el.on('show.bs.dropdown', function () {
			if (toggleVisibility) {
				el.find('.dropdown-toggle').css({ visibility: 'hidden' });
				searchEl.removeClass('hidden');
				searchEl.css({
					'z-index': el.find('.dropdown-toggle').css('z-index') + 1,
				});
			}

			function doSearch() {
				const val = searchEl.find('input').val();
				if (val.length > 1 || (!val && !categoriesList)) {
					loadList(val, function (categories) {
						categoriesList = options.cacheList && (categoriesList || categories);
						renderList(categories);
					});
				} else if (!val && categoriesList) {
					renderList(categoriesList);
				}
			}

			searchEl.on('click', function (ev) {
				ev.preventDefault();
				ev.stopPropagation();
			});
			searchEl.find('input').val('').on('keyup', utils.debounce(doSearch, 300));
			doSearch();
		});

		el.on('shown.bs.dropdown', function () {
			if (!['xs', 'sm'].includes(utils.findBootstrapEnvironment())) {
				searchEl.find('input').focus();
			}
		});

		forkModal.find('#fork-title').on('keyup', checkForkButtonEnable);

		postSelect.init(function () {
			checkForkButtonEnable();
			showPostsSelected();
		});
		showPostsSelected();

		forkCommit.on('click', createTopicFromPosts);
	});
};

function onAjaxifyEnd() {
	if (ajaxify.data.template.name !== 'topic' || ajaxify.data.tid !== fromTid) {
		closeForkModal();
		$(window).off('action:ajaxify.end', onAjaxifyEnd);
	}
}

function createTopicFromPosts() {
	if (!selectedCategory) {
		return;
	}
	forkCommit.attr('disabled', true);
	socket.emit('topics.createTopicFromPosts', {
		title: forkModal.find('#fork-title').val(),
		pids: postSelect.pids,
		fromTid: fromTid,
		cid: selectedCategory.cid,
	}, function (err, newTopic) {
		function fadeOutAndRemove(pid) {
			components.get('post', 'pid', pid).fadeOut(500, function () {
				$(this).remove();
			});
		}
		forkCommit.removeAttr('disabled');
		if (err) {
			return alerts.error(err.message);
		}

		alerts.alert({
			timeout: 5000,
			title: '[[global:alert.success]]',
			message: '[[topic:fork-success]]',
			type: 'success',
			clickfn: function () {
				ajaxify.go('topic/' + newTopic.slug);
			},
		});

		postSelect.pids.forEach(function (pid) {
			fadeOutAndRemove(pid);
		});

	});
};

function renderMenu(container) {
	if (!container) {
		return;
	}
	container.on('show.bs.dropdown', '.thread-tools', async function () {
		const $this = $(this);
		const dropdownMenu = $this.find('.dropdown-menu');
		const { top } = this.getBoundingClientRect();
		$this.toggleClass('dropup', top > window.innerHeight / 2);
		if (dropdownMenu.attr('data-loaded')) {
			return;
		}
		dropdownMenu.html(helpers.generatePlaceholderWave([8, 8, 8]));
		const data = await socket.emit('topics.loadTopicTools', { tid: ajaxify.data.tid, cid: ajaxify.data.cid });
		const html = await app.parseAndTranslate('partials/topic/topic-menu-list', data);
		$(dropdownMenu).attr('data-loaded', 'true').html(html);
		hooks.fire('action:topic.tools.load', {
			element: $(dropdownMenu),
		});
	});
}

